select
id, available_count, expired_count, total_generated, use_percentage, created_by, created_time, updated_by,
updated_time, is_deleted
from trial_code_statistics


        and id = #{id}


        and available_count = #{availableCount}


        and expired_count = #{expiredCount}


        and total_generated = #{totalGenerated}


        and use_percentage = #{usePercentage}


        and created_by = #{createdBy}


        and created_time = #{createdTime}


        and updated_by = #{updatedBy}


        and updated_time = #{updatedTime}


        and is_deleted = #{isDeleted}


limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from trial_code_statistics


        and id = #{id}


        and available_count = #{availableCount}


        and expired_count = #{expiredCount}


        and total_generated = #{totalGenerated}


        and use_percentage = #{usePercentage}


